import sys

def xor_range(x, y):
    def xor_to(n):
        if n < 0:
            return 0
        xor_values = [0, n, 2, 0, n ^ 2, 2, n ^ 2 ^ 1, 0]
        return xor_values[n % 8]

    return xor_to(y) ^ xor_to(x - 1)

def f(l, r):
    max_xor = 0
    for i in range(l, r + 1):
        for j in range(i, r + 1):
            current_xor = xor_range(i, j)
            if current_xor > max_xor:
                max_xor = current_xor
    return max_xor

n = int(sys.stdin.readline().strip())
l = int(sys.stdin.readline().strip(), 2)
r = int(sys.stdin.readline().strip(), 2)

result = f(l, r)
print(bin(result)[2:])
